import{_ as i,a0 as n,w as a,s,I as t,x as o,a1 as l,A as r,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"成為你所在社區的美好力量 | LCTT x X-CMD","titleTemplate":false,"description":"成為你所在社區的美好力量 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"成為你所在社區的美好力量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"成為你所在社區的美好力量 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20170119 Be a force for good in your community","title":"成為你所在社區的美好力量","tag":"201805","desc":""},"relativePath":"201805/20170119 Be a force for good in your community.md","filePath":"[post].md"}'),m={name:"201805/20170119 Be a force for good in your community.md"};function d(f,e,b,T,g,k){const p=n("Link");return a(),s("div",null,[e[19]||(e[19]=t("h1",{id:"成為你所在社區的美好力量",tabindex:"-1"},[o("成為你所在社區的美好力量 "),t("a",{class:"header-anchor",href:"#成為你所在社區的美好力量","aria-label":"Permalink to “成為你所在社區的美好力量”"},"​")],-1)),e[20]||(e[20]=t("blockquote",null,[t("p",null,"明白如何傳遞美好，瞭解積極意願的力量，以及更多。")],-1)),e[21]||(e[21]=t("p",null,[t("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/people_remote_teams_world.png?itok=_9DCHEel",alt:"Be a force for good in your community"})],-1)),e[22]||(e[22]=t("blockquote",null,[t("p",null,"圖片來自：opensource.com")],-1)),e[23]||(e[23]=t("p",null,"激烈的爭論是開源社區和開放組織的標誌特徵之一。在好的時候，這些爭論充滿活力和建設性。他們面紅耳赤的背後其實是幽默和善意。各方實事求是，共同解決問題，推動持續改進。對我們中的許多人來説，他們只是單純的喜歡而已。",-1)),e[24]||(e[24]=t("p",null,"然而在那些不好的日子裏，這些爭論演變成了對舊話題的反覆爭吵。或者我們用各種方式來傳遞傷害和相互攻擊，或是使用卑劣的手段，而這些侵蝕着我們社區的激情、信任和生產力。",-1)),t("p",null,[e[1]||(e[1]=o("我們茫然四顧，束手無策，因為社區的對話開始變得有毒。然而，正如 ",-1)),l(p,{href:"https://opensource.com/business/15/5/5-ways-promote-inclusive-environment"},{default:r(()=>[...e[0]||(e[0]=[o("DeLisa Alexander 最近的分享",-1)])]),_:1}),e[2]||(e[2]=o("，我們每個人都有很多方法可以成為我們社區的一種力量。",-1))]),e[25]||(e[25]=t("p",null,"在這個“開源文化”系列的第一篇文章中，我將分享一些策略，教你如何在這個關鍵時刻進行干預，引導每個人走向更積極、更有效率的方向。",-1)),e[26]||(e[26]=t("h3",{id:"不要將人推開-而是將人推向前方",tabindex:"-1"},[o("不要將人推開，而是將人推向前方 "),t("a",{class:"header-anchor",href:"#不要將人推開-而是將人推向前方","aria-label":"Permalink to “不要將人推開，而是將人推向前方”"},"​")],-1)),t("p",null,[e[4]||(e[4]=o("最近，我和我的朋友和同事 ",-1)),l(p,{href:"https://twitter.com/leadership_365"},{default:r(()=>[...e[3]||(e[3]=[o("Mark Rumbles",-1)])]),_:1}),e[5]||(e[5]=o(" 一起吃午飯。多年來，我們在許多支持開源文化和引領 Red Hat 的項目中合作。在這一天，Mark 問我，他看到我最近介入了一個郵件列表的對話，當其中的辯論越來越過分時我是怎麼堅持的。",-1))]),e[27]||(e[27]=u('<p>幸運的是，這事早已塵埃落定，事實上我幾乎忘記了談話的內容。然而，它讓我們開始討論如何在一個擁有數千名成員的社區裏，公開和坦率的辯論。</p><p>Mark 説了一些讓我印象深刻的話。他説:“你知道，作為一個社區，我們真的很擅長將人推開。但我想看到的是，我們更多的是互相扶持 <em>向前</em> 。”</p><p>Mark 是絕對正確的。在我們的社區裏，我們成為一種美好力量的最好的方法之一就是：以一種迫使每個人提升他們的行為的方式回應衝突，而不是使衝突升級的方式。</p><h3 id="積極意願假想" tabindex="-1">積極意願假想 <a class="header-anchor" href="#積極意願假想" aria-label="Permalink to “積極意願假想”">​</a></h3><p>我們可以從一個簡單的假想開始，當我們在一個激烈的對話中觀察到不良行為時：完全有可能該不良行為其實有着積極意願。</p><p>誠然，這不是一件容易的事情。當我看到一場辯論正在變得骯髒的跡象時，我停下來問自己，史蒂芬·科維（Steven Covey）所説的人性化問題是什麼：</p><blockquote><p>“為什麼一個理性、正直的人會做這樣的事情？”</p></blockquote><p>現在，如果他是你的一個“普通的觀察對象”—— 一個有消極行為傾向的社區成員——也許你的第一個想法是，“嗯，也許這個人是個不靠譜，不理智的人”</p><p>回過頭來説。我並不是説你讓你自欺欺人。這其實就是人性化的問題，不僅是因為它讓你理解別人的立場，它還讓你變得人性化。</p><p>而這反過來又能幫助你做出反應，或者從最有效率的地方進行干預。</p><h3 id="尋求瞭解社區異議的原因" tabindex="-1">尋求瞭解社區異議的原因 <a class="header-anchor" href="#尋求瞭解社區異議的原因" aria-label="Permalink to “尋求瞭解社區異議的原因”">​</a></h3><p>當我再一次問自己為什麼一個理性的、正直的人可能會做這樣的事情時，歸結為幾個原因:</p><ul><li>他認為沒人聆聽他</li><li>他認為沒人尊重他</li><li>他認為沒人理解他</li></ul><p>一個簡單的積極意願假想，我們可以適用於幾乎所有的不良行為，其實就是那個人想要被聆聽，被尊重，或被理解。我想這是相當合理的。</p><p>通過站在這個更客觀、更有同情心的角度，我們可以看到他們的行為幾乎肯定 <strong><em>不會</em></strong> 幫助他們得到他們想要的東西，而社區也會因此而受到影響。如果沒有我們的幫助的話。</p><p>對我來説，這激發了一個願望：幫助每個人從我們所處的這個醜陋的地方“擺脱困境”。</p><p>在我介入之前，我問自己一個後續的問題：是否有其他積極的意圖可能會驅使這種行為</p><p>容易想到的例子包括:</p><ul><li>他們擔心我們錯過了一些重要的東西，或者我們犯了一個錯誤，沒有人能看到它。</li><li>他們想感受到自己的貢獻的價值。</li><li>他們精疲力竭，因為在社區裏工作過度或者在他們的個人生活中發生了一些事情。</li><li>他們討厭一些東西被破壞，並感到沮喪，因為沒有人能看到造成的傷害或不便。</li><li>……諸如此類。</li></ul><p>有了這些，我就有了豐富的積極的意圖假想，我可以為他們的行為找到原因。我準備伸出援助之手，向他們提供一些幫助。</p><h3 id="傳遞美好-掙脱泥潭" tabindex="-1">傳遞美好，掙脱泥潭 <a class="header-anchor" href="#傳遞美好-掙脱泥潭" aria-label="Permalink to “傳遞美好，掙脱泥潭”">​</a></h3><p>什麼是 an out？（LCTT 譯註：類似與佛家“解脱法門”的意思）把它想像成一個逃跑的門。這是一種退出對話的方式，或者放棄不良的行為，恢復表現得像一個體面的人，而不是丟面子。是叫某人振作向上，而不是叫他走開。</p><p>你可能經歷過這樣的事情，在你的生活中，當 <em>你</em> 在一次談話中表現不佳時，咆哮着，大喊大叫，對某事大驚小怪，而有人慷慨地給 <em>你</em> 提供了一個台階下。也許他們選擇不去和你“抬槓”，相反，他們説了一些表明他們相信你是一個理性、正直的人，他們採用積極意願假想，比如:</p><blockquote><p>所以，嗯，我聽到的是你真的很擔心，你很沮喪，因為似乎沒有人在聽。或者你擔心我們忽略了它的重要性。是這樣對吧？</p></blockquote><p>於是乎：即使這不是完全正確的（也許你的意圖不那麼高尚），在那一刻，你可能抓住了他們提供給你的台階，並欣然接受了重新定義你的不良行為的機會。你幾乎可以肯定地轉向一個更富有成效的角度，甚至你自己可能都沒有意識到。</p><p>也許你這樣説，“哦，雖然不完全是這樣，但我只是擔心，我們這樣會走向歧途，我明白你説的，作為社區，我們不能同時解決所有問題，但如果我們不盡快解決這個問題，會有更多不好的事情要發生……”</p><p>最後，談話幾乎可以肯定地開始轉移到一個更有效率的方向。</p><p>我們都有機會讓一個沮喪的人掙脱泥潭，而這就是方法。</p><h3 id="壞行為還是壞人" tabindex="-1">壞行為還是壞人？ <a class="header-anchor" href="#壞行為還是壞人" aria-label="Permalink to “壞行為還是壞人？”">​</a></h3><p>如果這個人特別激動，他們可能不會聽到或者接受你給出的第一個台階。沒關係。最可能的是，他們遲鈍的大腦已經被史前曾經對人類生存至關重要的杏仁體接管了，他們需要更多的時間來認識到你並不是一個威脅。只是需要你保持温和的態度，堅定地對待他們，就好像他們 <em>曾經是</em> 一個理性、正直的人，看看會發生什麼。</p><p>根據我的經驗，這些社區干預以三種方式結束:</p><p>大多數情況下，這個人實際上 <em>是</em> 一個理性的人，很快，他們就感激地接受了這個事實。在這個過程中，每個人都跳出了“黑與白”，“贏或輸”的心態。人們開始思考創造性的選擇和“雙贏”的結果，每個人都將受益。</p><blockquote><p>為什麼一個理性、正直的人會做這樣的事呢？</p></blockquote><p>有時候，這個人天生不是特別理性或正直的，但當他被你以如此一致的、不知疲倦的、耐心的慷慨和善良的對待的時候，他們就會羞愧地從談話中撤退。這聽起來像是，“嗯，我想我已經説了所有要説的了。謝謝你聽我的意見”。或者，對於不那麼開明的人來説，“嗯，我厭倦了這種談話。讓我們結束吧。”（好的，謝謝）。</p><p>更少的情況是，這個人是一個“<em>壞人</em>”，或者在社區管理圈子裏，是一個“攪屎棍”。這些人確實存在，而且他們在演戲方面很有發展。你猜怎麼着？通過持續地以一種友善、慷慨、以社區為中心的方式，完全無視所有試圖使局勢升級的嘗試，你有效地將談話變成了一個對他們沒有興趣的領域。他們別無選擇，只能放棄它。你成為贏家。</p><p>這就是積極意願假想的力量。通過對憤怒和充滿敵意的言辭做出回應，優雅而有尊嚴地回應，你就能化解一場戰爭，理清混亂，解決棘手的問題，而且在這個過程中很有可能會交到一個新朋友。</p><p>我每次應用這個原則都成功嗎？見鬼，不會。但我從不後悔選擇了積極意願。但是我能生動的回想起，當我採用消極意願假想時，將問題變得更糟糕的場景。</p><p>現在輪到你了。我很樂意聽到你提出的一些策略和原則，當你的社區裏的對話變得激烈的時候，要成為一股好力量。在下面的評論中分享你的想法。</p><p>下次，我們將探索更多的方法，在你的社區裏成為一個美好力量，我將分享一些處理“壞脾氣先生”的技巧。</p><hr><p>作者簡介：</p><p><img src="https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/headshot-square_0.jpg?itok=FS97b9YD" alt=""></p><p>麗貝卡·費爾南德斯（Rebecca Fernandez）是紅帽公司（Red Hat）的首席就業品牌 + 通訊專家，是《開放組織》書籍的貢獻者，也是開源決策框架的維護者。她的興趣是開源和業務管理模型的開源方式。Twitter：@ruhbehka</p><hr>',44)),t("p",null,[e[7]||(e[7]=o("via: ",-1)),l(p,{href:"https://opensource.com/open-organization/17/1/force-for-good-community"},{default:r(()=>[...e[6]||(e[6]=[o("https://opensource.com/open-organization/17/1/force-for-good-community",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=o("作者：",-1)),l(p,{href:"https://opensource.com/users/rebecca"},{default:r(()=>[...e[8]||(e[8]=[o("Rebecca Fernandez",-1)])]),_:1}),e[12]||(e[12]=o(" 譯者：",-1)),l(p,{href:"https://github.com/chao-zhi"},{default:r(()=>[...e[9]||(e[9]=[o("chao-zhi",-1)])]),_:1}),e[13]||(e[13]=o(" 校對：",-1)),l(p,{href:"https://github.com/wxy"},{default:r(()=>[...e[10]||(e[10]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[16]||(e[16]=o("本文由 ",-1)),l(p,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[14]||(e[14]=[o("LCTT",-1)])]),_:1}),e[17]||(e[17]=o(" 原創編譯，",-1)),l(p,{href:"https://linux.cn/"},{default:r(()=>[...e[15]||(e[15]=[o("Linux中國",-1)])]),_:1}),e[18]||(e[18]=o(" 榮譽推出",-1))])])}const L=i(m,[["render",d]]);export{y as __pageData,L as default};
